import json,hashlib,subprocess,time,urllib.request,urllib.error,os
from pathlib import Path
P='/tmp/chess-nov10-native-replay';out=Path('testdata/strength_2026_11_10_native_replays.json')
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
bins={'deployed':'./main','baseline':'/tmp/chess-nov09-baseline-before-fast-mate'}; hashes={k:sha(v) for k,v in bins.items()}
assert hashes['deployed'].startswith('047a5626') and hashes['baseline'].startswith('b1148856')
source=Path('testdata/lichess_2026_11_10_loss_scan.json');data=json.loads(source.read_text());games={x['id']:x for x in data['games']}
fixtures={}
for name,gid,ply,ms,threads in [('classical','yA6gLPUd',19,27190,8),('rook','W692ODie',53,8000,4)]:
 r=next(r for r in games[gid]['positions'] if r['ply']==ply);fixtures[name]={'game':gid,'ply':ply,'fen':r['fen'],'played':r['playedUci'],'refBest16':r['best']['bestmove'],'thinkMs':ms,'threads':threads,'logContext':r['logContext']}
 Path(f'{P}-{name}-fen.txt').write_text(f"{r['fen']} | {gid}-ply{ply} | {r['best']['bestmove']} | {r['playedUci']}\n")
env=dict(x.split(b'=',1) for x in Path('/proc/2576270/environ').read_bytes().split(b'\0') if b'=' in x)
def idle():
 while True:
  try:
   req=urllib.request.Request('https://lichess.org/api/account/playing',headers={'Authorization':'Bearer '+env[b'LICHESS_TOKEN'].decode()})
   with urllib.request.urlopen(req,timeout=20) as response: games=json.load(response)['nowPlaying']
   if not games:return
   print('Waiting for live game',','.join(g['gameId'] for g in games),flush=True)
  except (urllib.error.URLError,TimeoutError) as e:
   if isinstance(e,urllib.error.HTTPError) and e.code not in (429,500,502,503,504):raise
   print('Waiting: playing status unavailable',flush=True)
  time.sleep(15)
def atomic(path,obj):
 tmp=Path(str(path)+'.tmp');tmp.write_text(json.dumps(obj,indent=2)+'\n');tmp.replace(path)
def run_native(name,variant,rep,attempt):
 f=fixtures[name];path=f'{P}-{name}-{variant}-{rep}-attempt{attempt}';assert sha(bins[variant])==hashes[variant]
 with open(path+'.txt','w') as o:
  proc=subprocess.run(['python3','/tmp/chess-oct10-idle-run.py',bins[variant],'abdada-bench','--fens',f'{P}-{name}-fen.txt','--think-ms',str(f['thinkMs']),'--threads',str(f['threads']),'--runs','1','--json',path+'.json'],stdout=o,stderr=subprocess.STDOUT)
 if proc.returncode in (75,130):return None
 if proc.returncode:raise RuntimeError(f'Failed {path}: {proc.returncode}')
 run=json.loads(Path(path+'.json').read_text())['positions'][0]['threads'][0]['runs'][0]
 return {'variant':variant,'rep':rep,'attempt':attempt,'result':run,'stdout':path+'.txt','json':path+'.json'}
records={n:[] for n in fixtures}
for name in ['classical','rook']:
 attempt=0
 while True:
  attempt+=1;idle();a=run_native(name,'deployed',1,attempt)
  if a is None:print('Excluded interrupted pair',name,attempt,flush=True);continue
  b=run_native(name,'baseline',1,attempt)
  if b is None:print('Excluded interrupted pair',name,attempt,flush=True);continue
  records[name].extend([a,b]);atomic(Path(f'{P}-{name}-pair-checkpoint.json'),[a,b]);print('Completed pair',name,json.dumps([a['result'],b['result']]),flush=True);break
for rep in (2,3):
 for name in (['rook','classical'] if rep==2 else ['classical','rook']):
  attempt=0
  while True:
   attempt+=1;idle();r=run_native(name,'deployed',rep,attempt)
   if r is None:print('Excluded interrupted',name,rep,attempt,flush=True);continue
   records[name].append(r);atomic(Path(f'{P}-{name}-deployed-{rep}-checkpoint.json'),r);print('Completed',name,rep,json.dumps(r['result']),flush=True);break
refs={}
for name,f in fixtures.items():
