fen,move=sys.argv[1:]
p=subprocess.Popen(['./stockfish'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,text=True)
def send(s): p.stdin.write(s+'\n');p.stdin.flush()
def wait(s):
 for line in p.stdout:
  if line.startswith(s):return
 raise RuntimeError('Stockfish terminated')
send('uci');wait('uciok');send('setoption name Threads value 1');send('isready');wait('readyok')
def analyze(forced):
 send('setoption name Clear Hash');send('isready');wait('readyok');send('position fen '+fen);send('go depth 22'+(' searchmoves '+move if forced else ''))
 last=None
 for line in p.stdout:
  m=re.search(r'^info depth (\d+) .*? score (cp|mate) (-?\d+)(?: (lowerbound|upperbound))? .*? pv (.+)',line)
  if m and int(m[1])==22 and not m[4]: last={'depth':int(m[1]),'score':{'type':m[2],'value':int(m[3])},'pv':m[5].split()}
  if line.startswith('bestmove'):
   if not last:raise RuntimeError('No complete depth22 score/PV: '+line)
   last['bestmove']=line.split()[1];return last
 raise RuntimeError('Stockfish terminated')
result={'best':analyze(False),'played':analyze(True)}
send('quit');p.wait();print(json.dumps(result))

