  class FakePath:
   def __init__(self,path):self.path=path
   def stat(self):return types.SimpleNamespace(st_size=len(initial))
   def read_bytes(self):return b'LICHESS_TOKEN=dummy\0'
   def open(self):
    class Reader:
     def __enter__(self):
      self.io=io.StringIO(storage.getvalue());return self.io
     def __exit__(self,*args):self.io.close()
    return Reader()
  class Child:
   pid=13
   returncode=None
   def poll(self):
    n=polls.pop(0) if polls else result
    if n is not None:self.returncode=n
    return n
   def wait(self):self.returncode=-15;return self.returncode
  child=Child(); calls=iter(statuses)
  def urlopen(*args,**kwargs):
   val=next(calls)
   if isinstance(val,Exception):raise val
   return io.StringIO(__import__('json').dumps({'nowPlaying':val}))
  def sleep(_):storage.seek(0,2);storage.write(game_log)
  def popen(*args,**kwargs):
   # Immediate completion scenarios can receive a log event before first poll.
   if len(polls)==1 and game_log:storage.seek(0,2);storage.write(game_log)
   return child
  with patch('pathlib.Path',FakePath),patch('urllib.request.urlopen',urlopen),patch('subprocess.Popen',popen),patch('os.killpg',side_effect=lambda *v:killed.append(v)),patch('time.sleep',sleep),patch.object(sys,'argv',[SCRIPT,'dummy']):
   with self.assertRaises(SystemExit) as ex:runpy.run_path(SCRIPT,run_name='__main__')
  return ex.exception.code,killed
 def test_child_finishes_between_polls_game_start(self):
  code,killed=self.run_case(polls=[None,0,0],game_log='gameFull',statuses=([],))
  self.assertEqual(code,130);self.assertEqual(killed,[])
