  ns=int(decimal.Decimal(match[1])*1000000000);ms=ns//1000000;threads=4 if ms<10000 else 8
  line=f"{r['fen']} | {g['id']}-ply{r['ply']} | {r['best']['bestmove']} | {r['playedUci']} | SF16 logged move; original budget {match[1]}s"
  jobs.append({'index':len(jobs),'group':'fresh7','line':line,'loggedBudgetNs':ns,'thinkMs':ms,'threads':threads,'loggedThinkingLine':r['logContext']['thinkingLine']})
